namespace CSharer.Core.Services {	 public class FileWatcherService 	{     	private FileSystemWatcher? _watcher;     	public event Action<string>? OnNewVideoDetected;      	public void Start(string folderPath)     	{         	if (!Directory.Exists(folderPath))         	{             	throw new DirectoryNotFoundException($"Folder not found: {folderPath}");         	}          	_watcher = new FileSystemWatcher(folderPath)         	{             	Filter = "*.mp4",             	NotifyFilter = NotifyFilters.FileName | NotifyFilters.CreationTime         	};          	_watcher.Created += (sender, e) =>         	{             	Console.WriteLine($"[{DateTime.Now:HH:mm:ss}] New video detected: {e.Name}");             	OnNewVideoDetected?.Invoke(e.FullPath);         	};          	_watcher.EnableRaisingEvents = true;         	Console.WriteLine($"👀 Watching folder: {folderPath}");     	}      	public void Stop()     	{         	_watcher?.Dispose();         	Console.WriteLine("⏸ Stopped watching folder");     	} 	} }
